// ============================================================================
// FAO HITL Approval Handler v2 — Validate Query Params (GET path)
// ----------------------------------------------------------------------------
// GET /webhook/fao-hitl-confirm?hitl_id=N&decision=X&approver_email=Y
//
// This endpoint is IDEMPOTENT and SIDE-EFFECT-FREE.
// It exists because Slack's link-expander GETs every URL in a posted
// message within ~2-3 seconds for unfurl/preview generation. If GET had
// side effects (as in v1), the expander would auto-resolve every HITL
// the moment the gateway posted to Slack. Empirically observed Apr 25
// (Exec IDs 11542-11547: 6 approval_handler hits within 3s of message).
//
// Architecture: GET shows a confirmation form; POST actually resolves.
// HTTP semantics restored: GET is safe, POST is the mutating action.
// ============================================================================

const params = $input.first().json.query || {};

const hitl_id_raw = params.hitl_id;
const decision = params.decision;
const approver_email = params.approver_email;

const hitl_id = parseInt(hitl_id_raw, 10);
if (!Number.isInteger(hitl_id) || hitl_id <= 0 || String(hitl_id) !== String(hitl_id_raw)) {
  throw new Error(
    `FAO-GOV-004 confirm: hitl_id query param must be a positive integer. Got: '${hitl_id_raw}'`
  );
}

if (decision !== 'APPROVED' && decision !== 'REJECTED') {
  throw new Error(
    `FAO-GOV-004 confirm: decision query param must be APPROVED or REJECTED. Got: '${decision}'`
  );
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(approver_email || '')) {
  throw new Error(
    `FAO-GOV-004 confirm: approver_email query param missing or invalid. Got: '${approver_email}'`
  );
}

return [{ json: {
  hitl_id,
  decision,
  approver_email,
  request_received_at: new Date().toISOString()
}}];

// ============================================================================
// FAO HITL Approval Handler v2 — Compose Confirmation HTML (GET response)
// ----------------------------------------------------------------------------
// Three rendering branches:
//   1. HITL not found       -> 404 page
//   2. HITL already decided -> 410 informational page (no form)
//   3. HITL pending         -> 200 confirmation form
//                              + RED SoD warning banner if self-approval
//
// SoD warning is informational (defense in depth). The actual SoD
// enforcement still runs at the database trigger on POST. Frontend
// warns; backend enforces. The user can still submit even on
// self-approval; the trigger then raises FAO-GOV-004 loudly, which is
// the demo screenshot.
// ============================================================================

const ctx = $('Validate Query Params').first().json;
const lookup_results = $input.all().map(i => i.json);
const row = lookup_results[0]; // undefined if 0 rows

const escape = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Common <head> CSS shared by all three branches
const styles = `
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif; background: #0e0e0e; color: #e6e6e6; max-width: 760px; margin: 60px auto; padding: 0 24px; line-height: 1.6; }
  h1 { font-size: 26px; margin-bottom: 8px; }
  h2 { color: #888; font-size: 13px; font-weight: 500; margin-top: 0; text-transform: uppercase; letter-spacing: 0.08em; }
  h3 { color: #aaa; font-size: 12px; font-weight: 500; margin-top: 28px; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 8px; }
  .control-id { display: inline-block; background: #1a2a1a; color: #99cc99; padding: 4px 10px; border-radius: 4px; font-family: 'SF Mono', Monaco, monospace; font-size: 12px; font-weight: 500; margin-bottom: 16px; }
  .control-id.danger { background: #2a1a1a; color: #ff9999; }
  code { background: #2a2a2a; padding: 2px 8px; border-radius: 3px; font-family: 'SF Mono', Monaco, monospace; font-size: 0.9em; color: #ffcc99; }
  .meta { font-size: 13px; padding: 18px; border: 1px solid #2a2a2a; border-radius: 6px; background: #161616; margin-top: 8px; }
  .meta p { margin: 6px 0; }
  .meta strong { color: #aaa; display: inline-block; width: 150px; font-weight: 500; }
  .rationale { padding: 16px; border-left: 3px solid #555; background: #161616; font-size: 13px; color: #ccc; }
  .sod-warning { background: #2a1a1a; border: 1px solid #ff6b6b; color: #ffaaaa; padding: 16px; border-radius: 6px; margin: 24px 0; font-size: 14px; }
  .sod-warning strong { color: #ff6b6b; }
  .actions { margin-top: 32px; display: flex; gap: 16px; align-items: center; }
  button { background: #4ade80; color: #0e0e0e; border: 0; padding: 12px 24px; border-radius: 6px; font-size: 14px; font-weight: 600; cursor: pointer; font-family: inherit; }
  button.reject { background: #fb923c; }
  button:hover { opacity: 0.9; }
  a.cancel { color: #888; font-size: 13px; text-decoration: none; }
  a.cancel:hover { color: #ccc; }
  .footer { color: #666; font-size: 12px; margin-top: 40px; padding-top: 16px; border-top: 1px solid #2a2a2a; }
`;

// ---- Branch 1: HITL not found ---------------------------------------------
if (!row) {
  const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>HITL Not Found \u2014 FinAgent OS</title><style>${styles}</style></head><body>
  <h2>FinAgent OS \u00b7 HITL Approval Handler</h2>
  <h1 style="color: #ff6b6b">HITL Not Found</h1>
  <span class="control-id danger">FAO-GOV-004</span>
  <p>HITL request <code>${escape(ctx.hitl_id)}</code> does not exist in <code>public.hitl_queue</code>.</p>
  <p>Check the link in the Slack message. If the issue persists, the request may have been deleted or the database state is inconsistent.</p>
  <p class="footer">Request: hitl_id=${escape(ctx.hitl_id)}, decision=${escape(ctx.decision)}, approver_email=${escape(ctx.approver_email)}</p>
</body></html>`;
  return [{ json: { html, status_code: 404 }}];
}

// ---- Branch 2: HITL already decided ---------------------------------------
if (row.current_decision !== 'PENDING') {
  const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>HITL Already Decided \u2014 FinAgent OS</title><style>${styles}</style></head><body>
  <h2>FinAgent OS \u00b7 HITL Approval Handler</h2>
  <h1 style="color: #fb923c">Already Decided</h1>
  <span class="control-id danger">FAO-GOV-004</span>
  <p>HITL request <code>#${escape(row.hitl_id)}</code> was already resolved as <code>${escape(row.current_decision)}</code>.</p>
  <div class="meta">
    <p><strong>Decision:</strong> <code>${escape(row.current_decision)}</code></p>
    <p><strong>Decided at:</strong> <code>${escape(row.current_decided_at)}</code></p>
    <p><strong>Approver UUID:</strong> <code>${escape(row.current_approver_id)}</code></p>
    <p><strong>Agent:</strong> <code>${escape(row.agent_id)}</code></p>
    <p><strong>Correlation:</strong> <code>${escape(row.correlation_id)}</code></p>
  </div>
  <p style="margin-top:24px">No further action needed. The shadow_ledger HITL_RESOLVED and COMMITTED events were already written.</p>
</body></html>`;
  return [{ json: { html, status_code: 410 }}];
}

// ---- Branch 3: HITL pending - render confirmation form --------------------
const is_self_approval = (row.agent_invoker_email === ctx.approver_email);
const is_approve = (ctx.decision === 'APPROVED');
const action_word = is_approve ? 'APPROVE' : 'REJECT';
const action_color = is_approve ? '#4ade80' : '#fb923c';
const btn_class = is_approve ? '' : 'reject';
const btn_label = is_approve ? `Confirm Approve` : `Confirm Reject`;

const sod_block = is_self_approval ? `
  <div class="sod-warning">
    <strong>\u26a0 Segregation of Duties Warning</strong><br>
    The approver email (<code>${escape(ctx.approver_email)}</code>) matches the agent invoker email. Submitting this confirmation will trigger <strong>FAO-GOV-004</strong> at the database (<code>hitl_queue_sod_guard</code> trigger) and the resolution will be rejected with a loud exception. This is by design \u2014 you cannot resolve your own invocation. Click Cancel and use a different approver's link.
  </div>` : '';

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>Confirm ${action_word} \u2014 FinAgent OS</title><style>${styles}</style></head><body>
  <h2>FinAgent OS \u00b7 HITL Approval Handler</h2>
  <h1 style="color: ${action_color}">Confirm ${action_word}</h1>
  <span class="control-id">FAO-GOV-004</span>
  <p>You are about to <strong style="color:${action_color}">${action_word}</strong> HITL request <code>#${escape(row.hitl_id)}</code> as <code>${escape(ctx.approver_email)}</code>.</p>
  ${sod_block}
  <h3>Execution Context</h3>
  <div class="meta">
    <p><strong>Agent:</strong> <code>${escape(row.agent_id)}</code></p>
    <p><strong>Risk Tier:</strong> <code>${escape(row.risk_tier)}</code> \u00b7 <strong>Sub-Tier:</strong> <code>${escape(row.sub_tier)}</code></p>
    <p><strong>Invoker:</strong> <code>${escape(row.agent_invoker_email)}</code></p>
    <p><strong>Correlation ID:</strong> <code>${escape(row.correlation_id)}</code></p>
    <p><strong>Created:</strong> <code>${escape(row.created_at)}</code></p>
    <p><strong>SLA timeout:</strong> <code>${escape(row.timeout_at)}</code></p>
  </div>
  <h3>Policy Rationale</h3>
  <div class="rationale">${escape(row.policy_rationale)}</div>
  <form method="POST" action="/webhook/fao-hitl-resolve" class="actions">
    <input type="hidden" name="hitl_id" value="${escape(row.hitl_id)}">
    <input type="hidden" name="decision" value="${escape(ctx.decision)}">
    <input type="hidden" name="approver_email" value="${escape(ctx.approver_email)}">
    <button type="submit" class="${btn_class}">${btn_label}</button>
    <a class="cancel" href="javascript:window.close()">Cancel \u2014 close tab</a>
  </form>
  <p class="footer">This page is read-only. The actual decision is recorded only when you click <strong>${btn_label}</strong> above. The form posts to <code>/webhook/fao-hitl-resolve</code> (POST), which is unreachable by Slack's link-expander or browser prefetch \u2014 only an explicit click submits.</p>
</body></html>`;

return [{ json: { html, status_code: 200 }}];

// ============================================================================
// FAO HITL Approval Handler v2 — Validate Body Params (POST path)
// ----------------------------------------------------------------------------
// POST /webhook/fao-hitl-resolve with form-urlencoded body:
//   hitl_id=N&decision=X&approver_email=Y
//
// This endpoint MUTATES state. Reachable only by explicit form submission
// (the Confirm button on the GET confirmation page). Slack's link-expander
// only does GET so it cannot reach this endpoint. Browser prefetch only
// does GET so it also cannot reach this endpoint. Cross-origin POST from
// a malicious site is the remaining classical CSRF surface; this demo
// does not implement CSRF tokens (production gap, documented).
// ============================================================================

const body = $input.first().json.body || {};

const hitl_id_raw = body.hitl_id;
const decision = body.decision;
const approver_email = body.approver_email;

const hitl_id = parseInt(hitl_id_raw, 10);
if (!Number.isInteger(hitl_id) || hitl_id <= 0 || String(hitl_id) !== String(hitl_id_raw)) {
  throw new Error(
    `FAO-GOV-004 resolve: hitl_id form field must be a positive integer. Got: '${hitl_id_raw}'`
  );
}

if (decision !== 'APPROVED' && decision !== 'REJECTED') {
  throw new Error(
    `FAO-GOV-004 resolve: decision form field must be APPROVED or REJECTED. Got: '${decision}'`
  );
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(approver_email || '')) {
  throw new Error(
    `FAO-GOV-004 resolve: approver_email form field missing or invalid. Got: '${approver_email}'`
  );
}

return [{ json: {
  hitl_id,
  decision,
  approver_email,
  decision_notes: 'Decision recorded via Slack approval link (confirmed via POST).',
  request_received_at: new Date().toISOString()
}}];

// ============================================================================
// FAO HITL Approval Handler v2 — Compose HITL_RESOLVED Writer Payload
// ============================================================================

const ctx_body    = $('Validate Body Params').first().json;
const ctx_resolve = $('Call fao_hitl_resolve').first().json;
const all_rows    = $input.all().map(item => item.json);

const started_row = all_rows.find(row => row.inputs && row.inputs.event_type === 'STARTED');
if (!started_row) {
  throw new Error(
    `FAO-GOV-004 resolve: no STARTED event found in shadow_ledger for correlation_id ${ctx_resolve.correlation_id}. Audit chain broken.`
  );
}

const execution_id = started_row.execution_id;

return [{ json: {
  correlation_id:      ctx_resolve.correlation_id,
  execution_id:        execution_id,
  agent_id:            ctx_resolve.agent_id,
  risk_tier:           ctx_resolve.risk_tier,
  inputs: {
    event_type:        'HITL_RESOLVED',
    hitl_id:           ctx_resolve.hitl_id,
    decision:          ctx_resolve.decision,
    approver_id:       ctx_resolve.approver_id,
    approver_email:    ctx_resolve.approver_email,
    agent_invoker_id:  ctx_resolve.agent_invoker_id,
    decided_at:        ctx_resolve.decided_at,
    sub_tier:          ctx_resolve.sub_tier,
    decision_notes:    ctx_body.decision_notes
  },
  ai_prompt:           null,
  ai_output:           null,
  ai_confidence:       null,
  fractional_cost_usd: null,
  policy_outcome:      'REQUIRE_HUMAN',
  policy_sub_tier:     ctx_resolve.sub_tier,
  policy_rationale:    `FAO-GOV-004 HITL resolved (hitl_id=${ctx_resolve.hitl_id}, decision=${ctx_resolve.decision}). Approver: ${ctx_resolve.approver_email} (id=${ctx_resolve.approver_id}). Invoker: ${ctx_resolve.agent_invoker_id}. Decided at: ${ctx_resolve.decided_at}. SoD enforced at hitl_queue_sod_guard trigger; this resolution passed because approver_id != agent_invoker_id.`,
  obligations:         [],
  hitl_status:         ctx_resolve.decision,
  hitl_approver_id:    ctx_resolve.approver_id,
  status:              'SUCCESS',
  error_details:       null
}}];

// ============================================================================
// FAO HITL Approval Handler v2 — Compose COMMITTED Writer Payload
// ============================================================================

const ctx_body    = $('Validate Body Params').first().json;
const ctx_resolve = $('Call fao_hitl_resolve').first().json;
const all_rows    = $('Read Shadow Ledger Events').all().map(item => item.json);

const started_row = all_rows.find(r => r.inputs && r.inputs.event_type === 'STARTED');
const asset_rows  = all_rows.filter(r => r.inputs && r.inputs.event_type === 'ASSET_RECONCILED');

if (!started_row || asset_rows.length === 0) {
  throw new Error(
    `FAO-GOV-004 resolve: incomplete shadow_ledger for correlation_id ${ctx_resolve.correlation_id} (started=${!!started_row}, asset_rows=${asset_rows.length}). Cannot compose COMMITTED.`
  );
}

const execution_id = started_row.execution_id;

const per_asset_summary = asset_rows.map(row => ({
  asset:           row.inputs.asset,
  band_status:     row.inputs.band_status,
  ratio:           row.inputs.ratio,
  policy_outcome:  row.policy_outcome,
  policy_sub_tier: row.policy_sub_tier
}));

const rank = { 'ALLOW': 0, 'ALLOW_WITH_OBLIGATIONS': 1, 'REQUIRE_HUMAN': 2, 'DENY': 3, 'BLOCKED': 4 };
let worst_outcome  = 'ALLOW';
let worst_sub_tier = null;
let worst_rank     = 0;
const all_obligations = new Set();

for (const row of asset_rows) {
  const r = rank[row.policy_outcome] ?? 0;
  if (r > worst_rank) {
    worst_rank      = r;
    worst_outcome   = row.policy_outcome;
    worst_sub_tier  = row.policy_sub_tier;
  } else if (r === worst_rank && row.policy_sub_tier === 'CRITICAL') {
    worst_sub_tier = 'CRITICAL';
  }
  for (const o of (row.obligations || [])) all_obligations.add(o);
}

const counts = {
  ALLOW:                  asset_rows.filter(r => r.policy_outcome === 'ALLOW').length,
  ALLOW_WITH_OBLIGATIONS: asset_rows.filter(r => r.policy_outcome === 'ALLOW_WITH_OBLIGATIONS').length,
  REQUIRE_HUMAN:          asset_rows.filter(r => r.policy_outcome === 'REQUIRE_HUMAN').length,
  DENY:                   asset_rows.filter(r => r.policy_outcome === 'DENY').length,
  BLOCKED:                asset_rows.filter(r => r.policy_outcome === 'BLOCKED').length
};

const escalated_assets = asset_rows
  .filter(r => rank[r.policy_outcome] >= 2)
  .map(r => r.inputs.asset);

const ledger_status = ctx_resolve.decision === 'APPROVED' ? 'SUCCESS' : 'ROLLED_BACK';

const rationale_parts = [
  `FAO-REC-001 execution committed after HITL resolution (hitl_id=${ctx_resolve.hitl_id}).`,
  `Agent classification (preserved): ${worst_outcome}${worst_sub_tier ? ' (' + worst_sub_tier + ')' : ''}.`,
  `Per-asset outcomes: ${counts.ALLOW} ALLOW, ${counts.ALLOW_WITH_OBLIGATIONS} ALLOW_WITH_OBLIGATIONS, ${counts.REQUIRE_HUMAN} REQUIRE_HUMAN${counts.DENY ? ', ' + counts.DENY + ' DENY' : ''}${counts.BLOCKED ? ', ' + counts.BLOCKED + ' BLOCKED' : ''}.`,
  escalated_assets.length > 0 ? `Escalated assets: ${escalated_assets.join(', ')}.` : null,
  `Human decision: ${ctx_resolve.decision} by ${ctx_resolve.approver_email}.`,
  `Execution termination: ${ledger_status}.`
].filter(Boolean);

return [{ json: {
  correlation_id:      ctx_resolve.correlation_id,
  execution_id:        execution_id,
  agent_id:            ctx_resolve.agent_id,
  risk_tier:           ctx_resolve.risk_tier,
  inputs: {
    event_type:        'COMMITTED',
    per_asset_summary: per_asset_summary,
    counts:            counts,
    escalated_assets:  escalated_assets,
    hitl_id:           ctx_resolve.hitl_id,
    decision:          ctx_resolve.decision,
    approver_id:       ctx_resolve.approver_id,
    approver_email:    ctx_resolve.approver_email,
    decided_at:        ctx_resolve.decided_at
  },
  ai_prompt:           null,
  ai_output:           null,
  ai_confidence:       null,
  fractional_cost_usd: null,
  policy_outcome:      worst_outcome,
  policy_sub_tier:     worst_sub_tier,
  policy_rationale:    rationale_parts.join(' '),
  obligations:         Array.from(all_obligations),
  hitl_status:         ctx_resolve.decision,
  hitl_approver_id:    ctx_resolve.approver_id,
  status:              ledger_status,
  error_details:       null
}}];

// ============================================================================
// FAO HITL Approval Handler v2 — Compose Success HTML Response
// ============================================================================

const ctx_resolve = $('Call fao_hitl_resolve').first().json;

const is_approved = ctx_resolve.decision === 'APPROVED';
const decision_color = is_approved ? '#4ade80' : '#fb923c';
const decision_label = is_approved ? 'Approved' : 'Rejected';
const decision_emoji = is_approved ? '\u2713' : '\u2717';
const decision_status = is_approved ? 'SUCCESS' : 'ROLLED_BACK';

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>HITL ${decision_label} \u2014 FinAgent OS</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif; background: #0e0e0e; color: #e6e6e6; max-width: 720px; margin: 60px auto; padding: 0 24px; line-height: 1.6; }
    h1 { color: ${decision_color}; font-size: 28px; margin-bottom: 8px; display: flex; align-items: center; gap: 16px; }
    h2 { color: #888; font-size: 13px; font-weight: 500; margin-top: 0; text-transform: uppercase; letter-spacing: 0.08em; }
    .check { display: inline-block; width: 48px; height: 48px; border-radius: 50%; background: ${decision_color}; color: #0e0e0e; font-size: 28px; font-weight: 700; text-align: center; line-height: 48px; }
    .control-id { display: inline-block; background: #1a2a1a; color: #99cc99; padding: 4px 10px; border-radius: 4px; font-family: 'SF Mono', Monaco, monospace; font-size: 12px; font-weight: 500; margin-bottom: 16px; }
    .meta { font-size: 13px; margin-top: 32px; padding: 20px; border: 1px solid #2a2a2a; border-radius: 6px; background: #161616; }
    .meta p { margin: 6px 0; }
    .meta strong { color: #aaa; display: inline-block; width: 130px; font-weight: 500; }
    code { background: #2a2a2a; padding: 2px 8px; border-radius: 3px; font-family: 'SF Mono', Monaco, monospace; font-size: 0.9em; color: #ffcc99; }
    .footer { color: #666; font-size: 12px; margin-top: 32px; padding-top: 16px; border-top: 1px solid #2a2a2a; }
    .audit-chain { color: #888; font-size: 12px; margin-top: 16px; font-family: 'SF Mono', Monaco, monospace; }
  </style>
</head>
<body>
  <h2>FinAgent OS \u00b7 HITL Approval Handler</h2>
  <h1><span class="check">${decision_emoji}</span><span>HITL ${decision_label}</span></h1>
  <span class="control-id">FAO-GOV-004</span>
  <p>Decision recorded. The shadow_ledger HITL_RESOLVED and COMMITTED events have been written; the execution audit chain is closed with status <code>${decision_status}</code>.</p>
  <div class="meta">
    <p><strong>HITL ID:</strong> <code>${ctx_resolve.hitl_id}</code></p>
    <p><strong>Correlation ID:</strong> <code>${ctx_resolve.correlation_id}</code></p>
    <p><strong>Agent:</strong> <code>${ctx_resolve.agent_id}</code></p>
    <p><strong>Decision:</strong> <code>${ctx_resolve.decision}</code></p>
    <p><strong>Approver:</strong> <code>${ctx_resolve.approver_email}</code></p>
    <p><strong>Decided at:</strong> <code>${ctx_resolve.decided_at}</code></p>
    <p><strong>Risk Tier:</strong> <code>${ctx_resolve.risk_tier}</code></p>
    <p><strong>Sub-Tier:</strong> <code>${ctx_resolve.sub_tier}</code></p>
  </div>
  <p class="footer">Segregation of duties enforced at the hitl_queue_sod_guard trigger (FAO-GOV-004). This resolution passed because the approver UUID does not equal the agent invoker UUID.</p>
  <p class="audit-chain">Audit chain: STARTED \u2192 ASSET_RECONCILED \u00d7 7 \u2192 HITL_REQUESTED \u2192 HITL_RESOLVED \u2192 COMMITTED</p>
</body>
</html>`;

return [{ json: { html, status_code: 200 }}];

// ============================================================================
// FAO HITL Approval Handler v2 — Compose Error HTML Response
// (Same forensic-dump approach as v1 fixed composer)
// ============================================================================

const ctx = $('Validate Body Params').first().json;
const err_item = $input.first().json;

const candidates = [];
function gather(obj, path) {
  if (obj == null) return;
  if (typeof obj === 'string') {
    if (obj.length > 0) candidates.push({ path, text: obj });
    return;
  }
  if (typeof obj !== 'object') return;
  for (const key of ['message', 'description', 'detail', 'hint', 'where']) {
    if (typeof obj[key] === 'string' && obj[key].length > 0) {
      candidates.push({ path: `${path}.${key}`, text: obj[key] });
    }
  }
  if (obj.cause)   gather(obj.cause,   `${path}.cause`);
  if (obj.context) gather(obj.context, `${path}.context`);
  if (obj.error)   gather(obj.error,   `${path}.error`);
}
gather(err_item.error,        'error');
gather(err_item.errorMessage, 'errorMessage');
gather(err_item,              'item');

const real_pg_error = candidates.find(c =>
  /FAO-GOV-|FAO-REC-|ERROR:|P00\d\d/.test(c.text) &&
  !c.text.startsWith('Failed query:')
);

const headline = real_pg_error
  ? real_pg_error.text
  : (candidates.find(c => !c.text.startsWith('Failed query:'))?.text
     || 'Could not extract a database error message.');

const is_sod              = /Segregation of Duties|cannot approve their own/i.test(headline);
const is_unknown_approver = /not in process_owners/i.test(headline);
const is_already_decided  = /not PENDING|already decided/i.test(headline);

let title, explanation;
if (is_sod) {
  title = 'Segregation of Duties Violation';
  explanation = `<p>Process owner <code>${ctx.approver_email}</code> attempted to approve their own agent invocation. This is rejected by FAO-GOV-004 \u2014 the segregation of duties control enforced at the database trigger layer (<code>hitl_queue_sod_guard</code>).</p>
     <p>To resolve this HITL request, click an approval link as a <em>different</em> process owner.</p>`;
} else if (is_unknown_approver) {
  title = 'Approver Not Recognized';
  explanation = `<p>The email <code>${ctx.approver_email}</code> does not match any seeded <code>process_owners</code> entry.</p>`;
} else if (is_already_decided) {
  title = 'Already Decided';
  explanation = `<p>HITL request <code>${ctx.hitl_id}</code> is no longer pending. It may have been resolved by another approver.</p>`;
} else {
  title = 'HITL Resolution Failed';
  explanation = `<p>The approval request could not be resolved.</p>`;
}

const status_code = is_sod ? 403 : 400;
const escape = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>${title} \u2014 FinAgent OS</title>
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif; background: #0e0e0e; color: #e6e6e6; max-width: 760px; margin: 60px auto; padding: 0 24px; line-height: 1.6; }
  h1 { color: #ff6b6b; font-size: 24px; margin-bottom: 8px; }
  h2 { color: #888; font-size: 13px; font-weight: 500; margin-top: 0; text-transform: uppercase; letter-spacing: 0.08em; }
  h3 { color: #aaa; font-size: 12px; font-weight: 500; margin-top: 32px; text-transform: uppercase; letter-spacing: 0.06em; }
  .control-id { display: inline-block; background: #2a1a1a; color: #ff9999; padding: 4px 10px; border-radius: 4px; font-family: 'SF Mono', Monaco, monospace; font-size: 12px; font-weight: 500; margin-bottom: 16px; }
  pre { background: #161616; border: 1px solid #2a2a2a; padding: 16px; border-radius: 6px; overflow-x: auto; font-size: 12px; color: #ffaaaa; white-space: pre-wrap; word-break: break-word; line-height: 1.5; }
  .meta { color: #888; font-size: 12px; margin-top: 32px; padding-top: 16px; border-top: 1px solid #2a2a2a; }
  .meta strong { color: #aaa; }
  code { background: #2a2a2a; padding: 2px 8px; border-radius: 3px; font-family: 'SF Mono', Monaco, monospace; font-size: 0.9em; color: #ffcc99; }
</style></head>
<body>
  <h2>FinAgent OS \u00b7 HITL Approval Handler</h2>
  <h1>${title}</h1>
  <span class="control-id">FAO-GOV-004</span>
  ${explanation}
  <h3>Database Error</h3>
  <pre>${escape(headline)}</pre>
  <div class="meta">
    <p><strong>Request:</strong> hitl_id=${ctx.hitl_id}, decision=${ctx.decision}, approver_email=${ctx.approver_email}</p>
    <p><strong>Time:</strong> ${ctx.request_received_at}</p>
  </div>
</body></html>`;

return [{ json: { html, status_code }}];
